window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-19391\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεσπέσιος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 344 na letra θ · nº geral 19391</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 de voz ou som divino 2 de origem divina; profético 3 que vem dos deuses; divino: θεσπεσίῃ [βουλῇ] hom. por vontade divina 4 sagrado 5 tard. inspirado por Deus; divino; santo 6 enviado por Deus (anjo) 7 maravilhoso; prodigioso; surpreendente ♦ ὁ θεσπέσιος [ἄγγελος] 8 mensageiro de deus ♦ θεσπέσιον ὡς ou οἷον adv. 9 maravilhosamente. 〈θέσπις〉</p></section></article>\n<article id=\"entry-dgp-19392\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεσπεσίως</h1><div class=\"entry-meta\"><span>DGP · ordem 345 na letra θ · nº geral 19392</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 divinamente 2 maravilhosamente; extraordinariamente 3 de maneira indizível.</p></section></article>\n<article id=\"entry-dgp-19393\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεσπιαί, ῶν (αἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 346 na letra θ · nº geral 19393</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Téspias, cidade da Beócia.</p></section></article>\n<article id=\"entry-dgp-19394\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεσπιᾶσιν</h1><div class=\"entry-meta\"><span>DGP · ordem 347 na letra θ · nº geral 19394</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em Téspias.</p></section></article>\n<article id=\"entry-dgp-19395\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεσπιδαής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 348 na letra θ · nº geral 19395</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aceso pelos deuses 2 que queima com uma violência extraordinária 3 prodigioso; extraordinário. 〈θέσπις, δαίω〉</p></section></article>\n<article id=\"entry-dgp-19396\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεσπιέπεια, ας</h1><div class=\"entry-meta\"><span>DGP · ordem 349 na letra θ · nº geral 19396</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) profético. 〈θέσπις, ἔπος〉</p></section></article>\n<article id=\"entry-dgp-19397\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεσπιεύς, έως</h1><div class=\"entry-meta\"><span>DGP · ordem 350 na letra θ · nº geral 19397</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 de Téspias ♦ οἱ Θεσπιεῖς 2 os téspios. 〈Θεσπιαί〉</p></section></article>\n<article id=\"entry-dgp-19398\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεσπίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 351 na letra θ · nº geral 19398</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. θεσπίσω e át. θεσπιῶ) 1 profetizar; proferir oráculos 2 anunciar algo, ac., a alguém, dat. 3 tard. (imperador) prescrever; determinar. 〈θέσπις〉</p></section></article>\n<article id=\"entry-dgp-19399\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θέσπις, ιος</h1><div class=\"entry-meta\"><span>DGP · ordem 352 na letra θ · nº geral 19399</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ιδος, ac. θέσπιν e θέσπιδα (masc., fem.) 1 que fala com os deuses; inspirado pela divindade; divino 2 prodigioso; extraordinário.</p></section></article>\n<article id=\"entry-dgp-19400\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θέσπισμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 353 na letra θ · nº geral 19400</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ordem divina 2 oráculo; vaticínio. 〈θεσπίζω〉</p></section></article>\n<article id=\"entry-dgp-19401\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεσπιῳδέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 354 na letra θ · nº geral 19401</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ser profeta; pronunciar um oráculo; profetizar 2 cantar por inspiração divina; cantar divinamente. 〈θεσπιῳδός〉</p></section></article>\n<article id=\"entry-dgp-19402\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεσπιῳδός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 355 na letra θ · nº geral 19402</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que canta uma profecia sob inspiração divina; profético ♦ ὁ, ἡ θεσπιῳδός 2 profeta, profetisa. 〈θέσπις, ᾠδή〉</p></section></article>\n<article id=\"entry-dgp-19403\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεσπρωτία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 356 na letra θ · nº geral 19403</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Tesprócia, região do Épiro.</p></section></article>\n<article id=\"entry-dgp-19404\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεσπρωτίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 357 na letra θ · nº geral 19404</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) natural de Tesprócia.</p></section></article>\n<article id=\"entry-dgp-19405\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεσπρωτός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 358 na letra θ · nº geral 19405</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">da Tesprócia, região a sudoeste do Épiro.</p></section></article>\n<article id=\"entry-dgp-19406\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεσσαλία,</h1><div class=\"entry-meta\"><span>DGP · ordem 359 na letra θ · nº geral 19406</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. Θετταλία, ας (ἡ) Tessália, região do norte da Grécia.</p></section></article>\n<article id=\"entry-dgp-19407\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεσσαλίζω,</h1><div class=\"entry-meta\"><span>DGP · ordem 360 na letra θ · nº geral 19407</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. θετταλίζω agir ou falar como um tessálio. 〈Θεσσαλός〉</p></section></article>\n<article id=\"entry-dgp-19408\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεσσαλιῆτις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 361 na letra θ · nº geral 19408</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) = Θεσσαλιῶτις.</p></section></article>\n<article id=\"entry-dgp-19409\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεσσαλικός,</h1><div class=\"entry-meta\"><span>DGP · ordem 362 na letra θ · nº geral 19409</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. Θετταλικός, ή, όν da Tessália, tessálio. 〈Θεσσαλία〉</p></section></article>\n<article id=\"entry-dgp-19410\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεσσαλίς,</h1><div class=\"entry-meta\"><span>DGP · ordem 363 na letra θ · nº geral 19410</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. Θετταλίς, ίδος (fem.) da Tessália, tessálio. 〈Θεσσαλία〉</p></section></article>\n<article id=\"entry-dgp-19411\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεσσαλιῶτις,</h1><div class=\"entry-meta\"><span>DGP · ordem 364 na letra θ · nº geral 19411</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. Θετταλιῶτις, ιδος (ἡ) Tessaliótida, parte da Tessália. 〈Θεσσαλία〉</p></section></article>\n<article id=\"entry-dgp-19412\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεσσαλονικεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 365 na letra θ · nº geral 19412</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. habitante de Tessalônica; tessalonicense. 〈Θεσσαλονίκη〉</p></section></article>\n<article id=\"entry-dgp-19413\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεσσαλονίκη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 366 na letra θ · nº geral 19413</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Tessalônica, filha de Filipe rei da Macedônia; cidade da Macedônia. 〈Θεσσαλός, νίκη〉</p></section></article>\n<article id=\"entry-dgp-19414\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεσσαλός,</h1><div class=\"entry-meta\"><span>DGP · ordem 367 na letra θ · nº geral 19414</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. Θετταλός, ή, όν da Tessália, Tessálio.</p></section></article>\n<article id=\"entry-dgp-19415\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεστιάς, άδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 368 na letra θ · nº geral 19415</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filha de Téstio, epít. de Altéia, de Leda.</p></section></article>\n<article id=\"entry-dgp-19416\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θέστιος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 369 na letra θ · nº geral 19416</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Téstios, rei mítico.</p></section></article>\n<article id=\"entry-dgp-19417\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεστόρειος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 370 na letra θ · nº geral 19417</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) filho de Testor, epít. de Calcas.</p></section></article>\n<article id=\"entry-dgp-19418\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεστορίδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 371 na letra θ · nº geral 19418</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. filho de Testor, Calcas ou Alcmeon.</p></section></article>\n<article id=\"entry-dgp-19419\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεσφατηλόγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 372 na letra θ · nº geral 19419</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que profere oráculos; profético. 〈θέσφατος, λόγος〉</p></section></article>\n<article id=\"entry-dgp-19420\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θέσφατος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 373 na letra θ · nº geral 19420</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 anunciado, predito ou ordenado pelos deuses; pressagiado: θέσφατόν ἐστι hom. é vontade dos deuses, or. inf. 2 de origem divina; divino: ἀὴρ θ. hom. ar divino 3 prodigioso; divino ♦ τὸ θέσφατον 4 predição; oráculo. 〈θεός, φατός〉</p></section></article>\n<article id=\"entry-dgp-19421\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θετέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 374 na letra θ · nº geral 19421</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de τίθημι.</p></section></article>\n<article id=\"entry-dgp-19422\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θετικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 375 na letra θ · nº geral 19422</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Jur. relativo à adoção (leis) 2 capaz de atribuir nomes 3 suscetível de afirmar 4 suscetível de ser posto em discussão 5 suscetível de ser posto como regra. 〈τίθημι〉</p></section></article>\n<article id=\"entry-dgp-19423\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θετικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 376 na letra θ · nº geral 19423</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 em aposição 2 positivamente; afirmativamente.</p></section></article>\n<article id=\"entry-dgp-19424\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θέτις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 377 na letra θ · nº geral 19424</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ιος, voc. Θέτι, ac. Θέτιν (ἡ) Tétis, deusa marinha, casada com Peleu, mãe de Aquiles.</p></section></article>\n<article id=\"entry-dgp-19425\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θετός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 378 na letra θ · nº geral 19425</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estabelecido; posto 2 adotado; adotivo (filho). 〈τίθημι〉</p></section></article>\n<article id=\"entry-dgp-19426\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θετταλία</h1><div class=\"entry-meta\"><span>DGP · ordem 379 na letra θ · nº geral 19426</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = Θεσσαλία.</p></section></article>\n<article id=\"entry-dgp-19427\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θετταλίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 380 na letra θ · nº geral 19427</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = θεσσαλίζω.</p></section></article>\n<article id=\"entry-dgp-19428\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θετταλικός</h1><div class=\"entry-meta\"><span>DGP · ordem 381 na letra θ · nº geral 19428</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = Θεσσαλικός.</p></section></article>\n<article id=\"entry-dgp-19429\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θετταλίς</h1><div class=\"entry-meta\"><span>DGP · ordem 382 na letra θ · nº geral 19429</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = Θεσσαλίς.</p></section></article>\n<article id=\"entry-dgp-19430\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεύσομαι, θεύσεαι</h1><div class=\"entry-meta\"><span>DGP · ordem 383 na letra θ · nº geral 19430</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1ª e 2ª sing. fut. poét. de θέω1.</p></section></article>\n<article id=\"entry-dgp-19431\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θέω1</h1><div class=\"entry-meta\"><span>DGP · ordem 384 na letra θ · nº geral 19431</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. θεύσομαι e θεύσω, aor. e perf. desus.) 1 correr: θ. πεδίοιο hom. correr pela planície, ἐπ᾽ ἄκρον ἁλός hom. correr sobre a superfície do mar 2 percorrer 3 disputar o prêmio da corrida: θ. περὶ τρίποδος hom. disputar a corrida por um tripé, τὸν περὶ τοῦ παντὸς δρόμον θέειν her. correr uma corrida decisiva (em que se arrisca tudo) 4 correr um risco; arriscar-se 5 (coisa) estender-se; propagar-se: φλὲψ ἀνὰ νῶτα θέουσα hom. veia que corre dorso acima.</p></section></article>\n<article id=\"entry-dgp-19432\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θέω2</h1><div class=\"entry-meta\"><span>DGP · ordem 385 na letra θ · nº geral 19432</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">brilhar.</p></section></article>\n<article id=\"entry-dgp-19433\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θέω3</h1><div class=\"entry-meta\"><span>DGP · ordem 386 na letra θ · nº geral 19433</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">subj. aor.2 poét. e jôn. de τίθημι.</p></section></article>\n<article id=\"entry-dgp-19434\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεωρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 387 na letra θ · nº geral 19434</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. θεωρήσω, aor. ἐθεώρησα, perf. τεθε­ώρηκα) 1 contemplar; olhar; observar: θ. γῆν πολλήν her. contemplar uma grande extensão de terra 2 ser espectador; assistir a, ac.: θ. τὰ Ὀλύμπια her. assistir aos jogos olímpicos, θ. ἀγῶνα her. ser espectador de uma disputa 3 ir como espectador a, εἰς e ac.: θ. ἐς Ὀλυμπίαν luc. ir como espectador a Olímpia 4 ser observador oficial; ser enviado como deputado (θεωρός) a festas ou para consultar oráculo 5 ver; considerar; examinar, ac., or. inter. 6 julgar por comparação; comparar, uma coisa, ac., com outra, dat. ou πρός e ac. 7 refletir; meditar sobre algo, περί e gen. 8 especular; interpretar 9 contemplar misticamente 10 Mil. passar em revista. 〈θεωρός〉</p></section></article>\n<article id=\"entry-dgp-19435\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεώρημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 388 na letra θ · nº geral 19435</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vista; espetáculo; objeto de contemplação, de observação 2 especulação; teoria; objeto de especulação 3 contemplação; pesquisa; meditação 4 norma; princípio; regra 5 preceito moral 6 esquema 7 Matem. teorema ♦ τὰ θεωρήματα 8 artes e ciências. 〈θεωρέω〉</p></section></article>\n<article id=\"entry-dgp-19436\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεωρητήριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 389 na letra θ · nº geral 19436</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lugar no teatro. 〈θεωρέω〉</p></section></article>\n<article id=\"entry-dgp-19437\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεωρητικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 390 na letra θ · nº geral 19437</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 capaz de perceber 2 levado a contemplar; próprio, conveniente à contemplação; contemplativo; especulativo. 〈θεωρητός〉</p></section></article>\n<article id=\"entry-dgp-19438\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεωρητός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 391 na letra θ · nº geral 19438</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se pode contemplar; visível; perceptível 2 que pode ser contemplado ou atingido pelo pensamento; inteligível. 〈θεωρέω〉</p></section></article>\n<article id=\"entry-dgp-19439\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεωρία, ας,</h1><div class=\"entry-meta\"><span>DGP · ordem 392 na letra θ · nº geral 19439</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. θεωρίη (ἡ) 1 ação de ver, de observar: θεωρίης εἵνεκεν ἐκδημεῖν her. viajar para ver o mundo 2 ação de ver uma festa, um espetáculo: ἀντὶ τῆς θεωρίας sóf. ao invés de ficar para ver as festas 3 festa solene; procissão 4 espetáculo 5 teoria, missão enviada por uma cidade às grandes festas de uma outra cidade 6 função de teoro, de deputado 7 contemplação pelo pensamento; consideração; meditação 8 teoria; especulação. 〈θεωρός〉</p></section></article>\n<article id=\"entry-dgp-19440\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεωρικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 393 na letra θ · nº geral 19440</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que concerne aos teoros; próprio da embaixada 2 que concerne aos lugares do teatro 3 de espetáculo; festivo ♦ τὸ θεωρικόν e τὰ θεωρικά 4 teóricon, dinheiro que se dava aos pobres para pagar o lugar no teatro. 〈θεωρία〉</p></section></article>\n<article id=\"entry-dgp-19441\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεωρίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 394 na letra θ · nº geral 19441</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 que diz respeito às teorias, às embaixadas♦ ἡ θεωρίς 2 [ναῦς] nau da teoria, navio sagrado que transportava os teoros 3 [ὁδός] caminho da teoria, percorrido pelos teoros ♦ αἱ θεωρίδες 4 sacerdotisas de Apolo Teoro.</p></section></article>\n<article id=\"entry-dgp-19442\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεωρός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 395 na letra θ · nº geral 19442</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 observador; contemplador que viaja para ver o mundo 2 espectador de jogos, de espetáculos públicos 3 teoro; embaixador enviado em missão a uma cidade para assistir a festas, consultar oráculo, recolher ofertas 4 magistrado.</p></section></article>\n<article id=\"entry-dgp-19443\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεώτερος</h1><div class=\"entry-meta\"><span>DGP · ordem 396 na letra θ · nº geral 19443</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comp. de θεός.</p></section></article>\n<article id=\"entry-dgp-19444\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θῆβαι, ῶν (αἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 397 na letra θ · nº geral 19444</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Tebas, n. de cidade da Beócia e de cidade egípcia. 〈Θήβη〉</p></section></article>\n<article id=\"entry-dgp-19445\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θηβαιεύς, έως</h1><div class=\"entry-meta\"><span>DGP · ordem 398 na letra θ · nº geral 19445</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) tebano. 〈Θῆβαι〉</p></section></article>\n<article id=\"entry-dgp-19446\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θηβαϊκός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 399 na letra θ · nº geral 19446</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tebano; de Tebas ♦ οἱ Θηβαῖοι 2 os tebanos. 〈Θῆβαι〉</p></section></article>\n<article id=\"entry-dgp-19447\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θηβαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 400 na letra θ · nº geral 19447</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Θηβαϊκός. 〈Θῆβαι〉</p></section></article>\n<article id=\"entry-dgp-19448\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θηβαΐς, ΐδος</h1><div class=\"entry-meta\"><span>DGP · ordem 401 na letra θ · nº geral 19448</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 de Tebas ♦ ἡ Θηβαΐς 2 região de Tebas, na Beócia 3 Tebaida, no Egito 4 Tebaida, poema épico sobre a guerra de Tebas após a morte de Édipo. 〈Θῆβαι〉</p></section></article>\n<article id=\"entry-dgp-19449\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θήβασδε</h1><div class=\"entry-meta\"><span>DGP · ordem 402 na letra θ · nº geral 19449</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. para Tebas; em direção a Tebas. 〈Θῆβαι, -δε〉</p></section></article>\n<article id=\"entry-dgp-19450\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θήβη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 403 na letra θ · nº geral 19450</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Tebe, n. de cidade da Beócia e da Tróade.</p></section></article>\n<article id=\"entry-dgp-19451\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θήβηθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 404 na letra θ · nº geral 19451</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de Tebas, na Beócia. 〈Θήβη, -θεν〉</p></section></article>\n<article id=\"entry-dgp-19452\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θήβῃσι(ν)</h1><div class=\"entry-meta\"><span>DGP · ordem 405 na letra θ · nº geral 19452</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em Tebas, na Beócia. 〈Θῆβαι〉</p></section></article>\n<article id=\"entry-dgp-19453\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηγάνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 406 na letra θ · nº geral 19453</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pedra de amolar 2 aguilhão; ferrão. 〈θήγω〉</p></section></article>\n<article id=\"entry-dgp-19454\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηγάνω</h1><div class=\"entry-meta\"><span>DGP · ordem 407 na letra θ · nº geral 19454</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">θήγω.</p></section></article>\n<article id=\"entry-dgp-19455\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θήγω</h1><div class=\"entry-meta\"><span>DGP · ordem 408 na letra θ · nº geral 19455</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. θήξω, aor. ἔθηξα, perf. desus.; perf. pas. τέθη­γμαι) 1 afiar; amolar: θ. ὀδόντα hom. [o javali] afiar as presas, θ. φάσγανον ésql. afiar a espada, λόγοι τεθηγμένοι ésql. palavras afiadas, mordazes 2 tornar agudo; excitar: θ. τὰς ψυχὰς εἰς τὰ πολεμικά xen. excitar as almas à guerra 3 intr. excitar-se ♦ méd. 4 afiar para si.</p></section></article>\n<article id=\"entry-dgp-19456\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 409 na letra θ · nº geral 19456</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. opt. 2ª sing. θηοῖο, part. jôn. θηεύμενος, impf. 1ª pl. ép. ἐθηεύμεσθα, 3ª pl. jôn. ἐθηεῦντο e θηεῦντο) ép. e jôn. = θεάομαι.</p></section></article>\n<article id=\"entry-dgp-19457\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηεύμενος, θηεῦντο</h1><div class=\"entry-meta\"><span>DGP · ordem 410 na letra θ · nº geral 19457</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. θηέομαι.</p></section></article>\n<article id=\"entry-dgp-19458\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θήῃς</h1><div class=\"entry-meta\"><span>DGP · ordem 411 na letra θ · nº geral 19458</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. subj. aor.2 de τίθημι.</p></section></article>\n<article id=\"entry-dgp-19459\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηητήρ, ῆρος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 412 na letra θ · nº geral 19459</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que olha com admiração; contemplador; admirador. 〈θηέομαι〉</p></section></article>\n<article id=\"entry-dgp-19460\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηΐον</h1><div class=\"entry-meta\"><span>DGP · ordem 413 na letra θ · nº geral 19460</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. cf. θεῖος2.</p></section></article>\n<article id=\"entry-dgp-19461\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηκαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 414 na letra θ · nº geral 19461</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">em forma de túmulo; sepulcral; funerário. 〈θήκη〉</p></section></article>\n<article id=\"entry-dgp-19462\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θήκη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 415 na letra θ · nº geral 19462</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 caixa; cofre; arca 2 bainha de espada 3 urna 4 túmulo. 〈τίθημι〉</p></section></article>\n<article id=\"entry-dgp-19463\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηκτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 416 na letra θ · nº geral 19463</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">afiado; amolado. 〈θήγω〉</p></section></article>\n<article id=\"entry-dgp-19464\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 417 na letra θ · nº geral 19464</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 amamentar; dar o seio 2 mamar 3 acalmar ♦ méd. 4 dar de mamar; aleitar: αἱ θηλαζόμεναι as amas de leite. 〈θηλή〉</p></section></article>\n<article id=\"entry-dgp-19465\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλασμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 418 na letra θ · nº geral 19465</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amamentação. 〈θηλάζω〉</p></section></article>\n<article id=\"entry-dgp-19466\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θήλεα</h1><div class=\"entry-meta\"><span>DGP · ordem 419 na letra θ · nº geral 19466</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">n. pl. e fem. jôn. de θῆλυς.</p></section></article>\n<article id=\"entry-dgp-19467\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θήλεας</h1><div class=\"entry-meta\"><span>DGP · ordem 420 na letra θ · nº geral 19467</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. pl. masc. de θῆλυς.</p></section></article>\n<article id=\"entry-dgp-19468\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλέη</h1><div class=\"entry-meta\"><span>DGP · ordem 421 na letra θ · nº geral 19468</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fem. jôn. de θῆλυς.</p></section></article>\n<article id=\"entry-dgp-19469\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 422 na letra θ · nº geral 19469</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ser abundante em algo, gen. ou dat. 2 florescer; estar florescente.</p></section></article>\n<article id=\"entry-dgp-19470\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 423 na letra θ · nº geral 19470</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mamilo 2 extremidade do seio 3 seio.</p></section></article>\n<article id=\"entry-dgp-19471\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλονή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 424 na letra θ · nº geral 19471</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ama de leite. 〈θηλή〉</p></section></article>\n<article id=\"entry-dgp-19472\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλυγενής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 425 na letra θ · nº geral 19472</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de mulher; do sexo feminino. 〈θῆλυς, γίγνομαι〉</p></section></article>\n<article id=\"entry-dgp-19473\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλυδρίας, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 426 na letra θ · nº geral 19473</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) efeminado. 〈θῆλυς, ὕδωρ〉</p></section></article>\n<article id=\"entry-dgp-19474\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλυκρατής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 427 na letra θ · nº geral 19474</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que domina as mulheres. 〈θῆλυς, κρατέω〉</p></section></article>\n<article id=\"entry-dgp-19475\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλυκτόνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 428 na letra θ · nº geral 19475</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que mata pela mão de uma mulher. 〈θῆλυς, κτείνω〉</p></section></article>\n<article id=\"entry-dgp-19476\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλυμίτρης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 429 na letra θ · nº geral 19476</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que ata nos cabelos fitas de mulher, ref. a Dioniso. 〈θῆλυς, μίτρα〉</p></section></article>\n<article id=\"entry-dgp-19477\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλύμιτρις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 430 na letra θ · nº geral 19477</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) = θηλυμίτρης.</p></section></article>\n<article id=\"entry-dgp-19478\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλύνοος-ους, οος-ους, οον-ουν</h1><div class=\"entry-meta\"><span>DGP · ordem 431 na letra θ · nº geral 19478</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem espírito ou pensamentos de mulher. 〈θῆλυς, νόος〉</p></section></article>\n<article id=\"entry-dgp-19479\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 432 na letra θ · nº geral 19479</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. desus., aor. ἐθήλυνα, perf. τεθήλυγκα; pas. aor. ἐθηλύνθην, perf. τεθήλυσμαι) 1 efeminar; tornar menos forte; tornar menos rude 2 enfraquecer; abrandar: θ. στόμα sóf. abrandar a rudeza da boca, da palavra ♦ méd. 3 vangloriar-se como uma mulher, de algo, dat. 〈θῆλυς〉</p></section></article>\n<article id=\"entry-dgp-19480\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλύπους, ους, ουν</h1><div class=\"entry-meta\"><span>DGP · ordem 433 na letra θ · nº geral 19480</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ποδος de um pé feminino. 〈θῆλυς, ποῦς〉</p></section></article>\n<article id=\"entry-dgp-19481\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θῆλυς, θήλεια</h1><div class=\"entry-meta\"><span>DGP · ordem 434 na letra θ · nº geral 19481</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e poét. θῆλυς, θῆλυ, gen. εος, είας, εος (comp. θηλύτερος, superl. θηλύτατος) 1 feminino: θή­λεια θεός hom. uma deusa, ἄπαις θήλεος γόνου her. sem descendência feminina, θήλεια ἵππος hom. égua 2 de mulher; que concerne à mulher: θήλεια φύσις plat. natureza feminina 3 terno; delicado; suave: θήλειαι παρειαί cal. faces delicadas 4 afeminado; mole: θ. δίαιτα plut. regime de vida feminino, θ. νοῦσος her. doença feminina, i.e., comportamento de homem devasso 5 fresco; refrescante: θῆλυς ἐέρση hom. sereno refrescante 6 produtivo: θῆλυ πεδίον cal. planície fértil, produtiva 7 comp. θηλύτερος feminino ♦ τὸ θῆλυ 8 número feminino, i.e., o número par, para os pitagóricos ♦ ἡ θήλεια 9 a mulher.</p></section></article>\n<article id=\"entry-dgp-19482\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλύσπορος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 435 na letra θ · nº geral 19482</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">produzido ou gerado por uma mulher. 〈θῆλυς, σπείρω〉</p></section></article>\n<article id=\"entry-dgp-19483\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλύτατος, θηλύτερος</h1><div class=\"entry-meta\"><span>DGP · ordem 436 na letra θ · nº geral 19483</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. θῆλυς.</p></section></article>\n<article id=\"entry-dgp-19484\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλύτης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 437 na letra θ · nº geral 19484</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 caráter feminino; natureza feminina 2 sensualidade feminina 3 natureza efeminada. 〈θῆλυς〉</p></section></article>\n<article id=\"entry-dgp-19485\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλυφανής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 438 na letra θ · nº geral 19485</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem a aparência de mulher; de mulher; feminino. 〈θῆλυς, φαίνω〉</p></section></article>\n<article id=\"entry-dgp-19486\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλύφωνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 439 na letra θ · nº geral 19486</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de voz feminina. 〈θῆλυς, φωνή〉</p></section></article>\n<article id=\"entry-dgp-19487\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλυχίτων, ωνος</h1><div class=\"entry-meta\"><span>DGP · ordem 440 na letra θ · nº geral 19487</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) vestido com túnica de mulher; vestido de mulher. 〈θῆλυς, χιτών〉</p></section></article>\n<article id=\"entry-dgp-19488\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηλώ, οῦς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 441 na letra θ · nº geral 19488</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ama de leite; nutriz. 〈θηλή〉</p></section></article>\n<article id=\"entry-dgp-19489\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θἤμισυ</h1><div class=\"entry-meta\"><span>DGP · ordem 442 na letra θ · nº geral 19489</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase át. de τὸ ἥμισυ.</p></section></article>\n<article id=\"entry-dgp-19490\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θημών, ῶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 443 na letra θ · nº geral 19490</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pilha; monte (de coisas, de cereais). 〈τίθημι〉</p></section></article>\n";
